-- Test 1 papers for Nanny / House Maid and Security Guard: 20 questions each, 10 shown at random.

SELECT 'Nanny / House Maid', NULL, 10, 'random_active', '{}'::uuid[], 70, true
WHERE NOT EXISTS (SELECT 1 FROM public.skill_quiz_configs c WHERE c.skill_code = 'Nanny / House Maid' AND c.region IS NULL);
UPDATE public.skill_quiz_configs SET questions_to_show = 10, selection_mode = 'random_active', selected_ids = '{}'::uuid[], active = true, updated_at = now() WHERE region IS NULL AND skill_code = 'Nanny / House Maid';
DELETE FROM public.worker_skill_quiz_responses WHERE quiz_item_id IN (SELECT id FROM public.worker_skill_quiz_items WHERE skill_code = 'Nanny / House Maid');
DELETE FROM public.worker_skill_quiz_items WHERE skill_code = 'Nanny / House Maid';

SELECT 'Security Guard', NULL, 10, 'random_active', '{}'::uuid[], 70, true
WHERE NOT EXISTS (SELECT 1 FROM public.skill_quiz_configs c WHERE c.skill_code = 'Security Guard' AND c.region IS NULL);
UPDATE public.skill_quiz_configs SET questions_to_show = 10, selection_mode = 'random_active', selected_ids = '{}'::uuid[], active = true, updated_at = now() WHERE region IS NULL AND skill_code = 'Security Guard';
DELETE FROM public.worker_skill_quiz_responses WHERE quiz_item_id IN (SELECT id FROM public.worker_skill_quiz_items WHERE skill_code = 'Security Guard');
DELETE FROM public.worker_skill_quiz_items WHERE skill_code = 'Security Guard';
