INSERT INTO public.skill_quiz_configs (skill_code, region, questions_to_show, selection_mode, selected_ids, pass_score, active)
INSERT INTO public.worker_skill_quiz_items (skill_code, question, question_hi, options, correct_option, sort_order) VALUES
  ('Nanny / House Maid', 'What should you do before cleaning a room?', 'कमरे की सफाई शुरू करने से पहले आपको क्या करना चाहिए?', '[{"id": "A", "en": "Start throwing things away", "hi": "सामान फेंकना शुरू करें"}, {"id": "B", "en": "Organise the cleaning materials", "hi": "सफाई का सामान तैयार करें"}, {"id": "C", "en": "Switch off all lights", "hi": "सभी लाइट बंद करें"}, {"id": "D", "en": "Leave the room", "hi": "कमरा छोड़ दें"}]'::jsonb, 'B', 1),
  ('Nanny / House Maid', 'Which material is commonly used to clean glass?', 'कांच साफ करने के लिए आमतौर पर किस चीज का उपयोग किया जाता है?', '[{"id": "A", "en": "Glass cleaner", "hi": "ग्लास क्लीनर"}, {"id": "B", "en": "Cooking oil", "hi": "खाने का तेल"}, {"id": "C", "en": "Flour", "hi": "आटा"}, {"id": "D", "en": "Sugar", "hi": "चीनी"}]'::jsonb, 'A', 2),
  ('Nanny / House Maid', 'How should you clean a dusty table?', 'धूल भरी मेज को कैसे साफ करना चाहिए?', '[{"id": "A", "en": "With a clean cloth", "hi": "साफ कपड़े से"}, {"id": "B", "en": "With cooking oil", "hi": "खाने के तेल से"}, {"id": "C", "en": "With dirty water", "hi": "गंदे पानी से"}, {"id": "D", "en": "With shoes", "hi": "जूतों से"}]'::jsonb, 'A', 3),
  ('Nanny / House Maid', 'What should you do after cleaning the bathroom?', 'बाथरूम की सफाई के बाद आपको क्या करना चाहिए?', '[{"id": "A", "en": "Leave it wet", "hi": "गीला छोड़ दें"}, {"id": "B", "en": "Keep it clean and dry", "hi": "साफ और सूखा रखें"}, {"id": "C", "en": "Throw cleaning tools inside", "hi": "सफाई का सामान अंदर फेंक दें"}, {"id": "D", "en": "Close the drain", "hi": "नाली बंद कर दें"}]'::jsonb, 'B', 4),
  ('Nanny / House Maid', 'Where should cleaning chemicals be stored?', 'सफाई के केमिकल कहां रखने चाहिए?', '[{"id": "A", "en": "Near food", "hi": "खाने के पास"}, {"id": "B", "en": "In children''s play area", "hi": "बच्चों के खेलने की जगह"}, {"id": "C", "en": "In a safe designated place", "hi": "सुरक्षित निर्धारित जगह पर"}, {"id": "D", "en": "In drinking water bottles", "hi": "पीने के पानी की बोतलों में"}]'::jsonb, 'C', 5),
  ('Nanny / House Maid', 'What should you do before preparing food?', 'खाना बनाने से पहले आपको क्या करना चाहिए?', '[{"id": "A", "en": "Wash your hands", "hi": "हाथ धोने चाहिए"}, {"id": "B", "en": "Touch your shoes", "hi": "जूते छूने चाहिए"}, {"id": "C", "en": "Clean the floor only", "hi": "केवल फर्श साफ करना चाहिए"}, {"id": "D", "en": "Start cooking immediately", "hi": "तुरंत खाना बनाना शुरू करना चाहिए"}]'::jsonb, 'A', 6),
  ('Nanny / House Maid', 'How should raw vegetables be prepared before cooking?', 'कच्ची सब्जियों को पकाने से पहले कैसे तैयार करना चाहिए?', '[{"id": "A", "en": "Wash them properly", "hi": "अच्छी तरह धोना चाहिए"}, {"id": "B", "en": "Keep them dirty", "hi": "गंदा रखना चाहिए"}, {"id": "C", "en": "Mix them with soap", "hi": "साबुन मिलाना चाहिए"}, {"id": "D", "en": "Keep them on the floor", "hi": "फर्श पर रखना चाहिए"}]'::jsonb, 'A', 7),
  ('Nanny / House Maid', 'What should you do if you smell gas in the kitchen?', 'अगर रसोई में गैस की गंध आए तो आपको क्या करना चाहिए?', '[{"id": "A", "en": "Switch on the lights", "hi": "लाइट चालू करें"}, {"id": "B", "en": "Ignore it", "hi": "नजरअंदाज करें"}, {"id": "C", "en": "Avoid flames and switches, ventilate if safe, and alert the responsible person", "hi": "आग और बिजली के स्विच से दूर रहें, सुरक्षित हो तो हवा आने दें और जिम्मेदार व्यक्ति को बताएं"}, {"id": "D", "en": "Continue cooking", "hi": "खाना बनाते रहें"}]'::jsonb, 'C', 8),
  ('Nanny / House Maid', 'How should cooked food be stored?', 'पके हुए खाने को कैसे रखना चाहिए?', '[{"id": "A", "en": "Open on the floor", "hi": "फर्श पर खुला रखें"}, {"id": "B", "en": "In a clean, covered container", "hi": "साफ और ढके हुए बर्तन में"}, {"id": "C", "en": "Near garbage", "hi": "कूड़े के पास"}, {"id": "D", "en": "Outside in direct sunlight", "hi": "सीधी धूप में"}]'::jsonb, 'B', 9),
  ('Nanny / House Maid', 'What should you do after using a kitchen knife?', 'रसोई में चाकू इस्तेमाल करने के बाद क्या करना चाहिए?', '[{"id": "A", "en": "Leave it anywhere", "hi": "कहीं भी छोड़ दें"}, {"id": "B", "en": "Keep it safely in its proper place", "hi": "सुरक्षित निर्धारित जगह पर रखें"}, {"id": "C", "en": "Put it in the sink under water", "hi": "सिंक में पानी के नीचे डाल दें"}, {"id": "D", "en": "Give it to a child", "hi": "बच्चे को दे दें"}]'::jsonb, 'B', 10),
  ('Nanny / House Maid', 'What should you do before feeding a baby?', 'बच्चे को खाना खिलाने से पहले आपको क्या करना चाहिए?', '[{"id": "A", "en": "Wash your hands", "hi": "हाथ धोएं"}, {"id": "B", "en": "Give food immediately", "hi": "तुरंत खाना दें"}, {"id": "C", "en": "Leave the baby alone", "hi": "बच्चे को अकेला छोड़ दें"}, {"id": "D", "en": "Give any available food", "hi": "कोई भी खाना दे दें"}]'::jsonb, 'A', 11),
  ('Nanny / House Maid', 'What should you do if a baby starts crying?', 'अगर बच्चा रोने लगे तो आपको क्या करना चाहिए?', '[{"id": "A", "en": "Shout at the baby", "hi": "बच्चे पर चिल्लाएं"}, {"id": "B", "en": "Ignore the baby", "hi": "बच्चे को नजरअंदाज करें"}, {"id": "C", "en": "Check whether the baby is hungry, uncomfortable or needs attention", "hi": "देखें कि बच्चा भूखा है, असहज है या उसे देखभाल चाहिए"}, {"id": "D", "en": "Leave the baby alone", "hi": "बच्चे को अकेला छोड़ दें"}]'::jsonb, 'C', 12),
  ('Nanny / House Maid', 'Can you leave a small child alone near water?', 'क्या छोटे बच्चे को पानी के पास अकेला छोड़ सकते हैं?', '[{"id": "A", "en": "Yes", "hi": "हां"}, {"id": "B", "en": "No", "hi": "नहीं"}, {"id": "C", "en": "Only for five minutes", "hi": "केवल पांच मिनट के लिए"}, {"id": "D", "en": "Only at night", "hi": "केवल रात में"}]'::jsonb, 'B', 13),
  ('Nanny / House Maid', 'What should you do if a child gets injured?', 'अगर बच्चे को चोट लग जाए तो आपको क्या करना चाहिए?', '[{"id": "A", "en": "Hide the injury", "hi": "चोट छिपाएं"}, {"id": "B", "en": "Inform the parents or responsible adult immediately and seek appropriate help", "hi": "माता-पिता या जिम्मेदार व्यक्ति को तुरंत बताएं और उचित सहायता लें"}, {"id": "C", "en": "Ignore it", "hi": "नजरअंदाज करें"}, {"id": "D", "en": "Scold the child", "hi": "बच्चे को डांटें"}]'::jsonb, 'B', 14),
  ('Nanny / House Maid', 'What should you do while a child is sleeping?', 'जब बच्चा सो रहा हो तो आपको क्या करना चाहिए?', '[{"id": "A", "en": "Follow the parents'' care instructions and ensure a safe sleeping environment", "hi": "माता-पिता के निर्देशों का पालन करें और सुरक्षित सोने का वातावरण सुनिश्चित करें"}, {"id": "B", "en": "Give the child toys", "hi": "बच्चे को खिलौने दें"}, {"id": "C", "en": "Leave the house", "hi": "घर से बाहर चले जाएं"}, {"id": "D", "en": "Play loud music", "hi": "तेज आवाज में संगीत चलाएं"}]'::jsonb, 'A', 15),
  ('Nanny / House Maid', 'What should you do if you do not understand your employer''s instructions?', 'अगर आपको मालिक की बात समझ में नहीं आती है तो आपको क्या करना चाहिए?', '[{"id": "A", "en": "Guess the work", "hi": "अंदाजा लगाएं"}, {"id": "B", "en": "Ask politely for clarification", "hi": "विनम्रता से दोबारा समझाने के लिए कहें"}, {"id": "C", "en": "Ignore the instructions", "hi": "निर्देशों को नजरअंदाज करें"}, {"id": "D", "en": "Refuse all work", "hi": "सारा काम मना कर दें"}]'::jsonb, 'B', 16),
  ('Nanny / House Maid', 'What should you do if you accidentally break something?', 'अगर गलती से कोई सामान टूट जाए तो क्या करना चाहिए?', '[{"id": "A", "en": "Hide it", "hi": "छिपा दें"}, {"id": "B", "en": "Blame someone else", "hi": "किसी और पर आरोप लगाएं"}, {"id": "C", "en": "Inform the employer honestly", "hi": "ईमानदारी से मालिक को बताएं"}, {"id": "D", "en": "Leave the house", "hi": "घर छोड़ दें"}]'::jsonb, 'C', 17),
  ('Nanny / House Maid', 'Why is punctuality important?', 'समय पर काम पर पहुंचना क्यों जरूरी है?', '[{"id": "A", "en": "It shows responsibility", "hi": "यह जिम्मेदारी दर्शाता है"}, {"id": "B", "en": "It wastes time", "hi": "इससे समय बर्बाद होता है"}, {"id": "C", "en": "It is not important", "hi": "यह जरूरी नहीं है"}, {"id": "D", "en": "It creates problems", "hi": "इससे परेशानी होती है"}]'::jsonb, 'A', 18),
  ('Nanny / House Maid', 'What should you do if you feel unwell during work?', 'काम के दौरान आपकी तबीयत खराब हो जाए तो क्या करना चाहिए?', '[{"id": "A", "en": "Hide it", "hi": "छिपाएं"}, {"id": "B", "en": "Inform the employer or responsible person", "hi": "मालिक या जिम्मेदार व्यक्ति को बताएं"}, {"id": "C", "en": "Continue dangerous work", "hi": "जोखिम भरा काम जारी रखें"}, {"id": "D", "en": "Ignore your health", "hi": "अपनी सेहत को नजरअंदाज करें"}]'::jsonb, 'B', 19),
  ('Nanny / House Maid', 'How should you handle your employer''s personal belongings?', 'मालिक के निजी सामान के साथ आपको कैसा व्यवहार करना चाहिए?', '[{"id": "A", "en": "Use them without permission", "hi": "बिना अनुमति इस्तेमाल करें"}, {"id": "B", "en": "Take them home", "hi": "घर ले जाएं"}, {"id": "C", "en": "Respect their privacy and belongings", "hi": "उनकी निजता और सामान का सम्मान करें"}, {"id": "D", "en": "Give them to others", "hi": "दूसरों को दे दें"}]'::jsonb, 'C', 20);
INSERT INTO public.skill_quiz_configs (skill_code, region, questions_to_show, selection_mode, selected_ids, pass_score, active)
INSERT INTO public.worker_skill_quiz_items (skill_code, question, question_hi, options, correct_option, sort_order) VALUES
  ('Security Guard', 'What is the main duty of a security guard?', 'सिक्योरिटी गार्ड का मुख्य काम क्या होता है?', '[{"id": "A", "en": "Cooking food", "hi": "खाना बनाना"}, {"id": "B", "en": "Protecting people and property", "hi": "लोगों और संपत्ति की सुरक्षा करना"}, {"id": "C", "en": "Repairing vehicles", "hi": "गाड़ी की मरम्मत करना"}, {"id": "D", "en": "Selling products", "hi": "सामान बेचना"}]'::jsonb, 'B', 1),
  ('Security Guard', 'What should a security guard do while on duty?', 'ड्यूटी के दौरान सिक्योरिटी गार्ड को क्या करना चाहिए?', '[{"id": "A", "en": "Sleep", "hi": "सोना चाहिए"}, {"id": "B", "en": "Use mobile games", "hi": "मोबाइल पर गेम खेलना चाहिए"}, {"id": "C", "en": "Stay alert and attentive", "hi": "सतर्क और ध्यान से रहना चाहिए"}, {"id": "D", "en": "Leave the assigned area", "hi": "अपनी जगह छोड़ देनी चाहिए"}]'::jsonb, 'C', 2),
  ('Security Guard', 'Why is wearing a security uniform important?', 'सिक्योरिटी यूनिफॉर्म पहनना क्यों जरूरी है?', '[{"id": "A", "en": "To identify the security guard", "hi": "सिक्योरिटी गार्ड की पहचान के लिए"}, {"id": "B", "en": "To look fashionable", "hi": "फैशन के लिए"}, {"id": "C", "en": "To avoid work", "hi": "काम से बचने के लिए"}, {"id": "D", "en": "To sleep comfortably", "hi": "आराम से सोने के लिए"}]'::jsonb, 'A', 3),
  ('Security Guard', 'What should you do when you see a suspicious person?', 'अगर आपको कोई संदिग्ध व्यक्ति दिखाई दे तो क्या करना चाहिए?', '[{"id": "A", "en": "Ignore the person", "hi": "नजरअंदाज करें"}, {"id": "B", "en": "Inform the supervisor and follow security procedures", "hi": "सुपरवाइजर को बताएं और सुरक्षा नियमों का पालन करें"}, {"id": "C", "en": "Start fighting", "hi": "लड़ाई शुरू करें"}, {"id": "D", "en": "Leave the area", "hi": "जगह छोड़ दें"}]'::jsonb, 'B', 4),
  ('Security Guard', 'What is a security patrol?', 'सिक्योरिटी पेट्रोल का क्या मतलब है?', '[{"id": "A", "en": "Walking around an assigned area to check safety", "hi": "निर्धारित क्षेत्र में घूमकर सुरक्षा जांच करना"}, {"id": "B", "en": "Taking a lunch break", "hi": "खाना खाने जाना"}, {"id": "C", "en": "Cleaning the office", "hi": "ऑफिस साफ करना"}, {"id": "D", "en": "Driving a bus", "hi": "बस चलाना"}]'::jsonb, 'A', 5),
  ('Security Guard', 'What should you do when a visitor enters a building?', 'जब कोई व्यक्ति बिल्डिंग में आता है तो आपको क्या करना चाहिए?', '[{"id": "A", "en": "Ignore the visitor", "hi": "नजरअंदाज करें"}, {"id": "B", "en": "Welcome and ask for the purpose of visit", "hi": "स्वागत करें और आने का कारण पूछें"}, {"id": "C", "en": "Allow everyone without checking", "hi": "बिना जांच सभी को आने दें"}, {"id": "D", "en": "Shout at the visitor", "hi": "चिल्लाएं"}]'::jsonb, 'B', 6),
  ('Security Guard', 'What should you check before allowing entry to a restricted area?', 'प्रतिबंधित क्षेत्र में प्रवेश देने से पहले क्या जांचना चाहिए?', '[{"id": "A", "en": "Visitor''s clothes", "hi": "कपड़े"}, {"id": "B", "en": "Visitor''s food", "hi": "खाना"}, {"id": "C", "en": "Valid permission or access authorization", "hi": "वैध अनुमति या प्रवेश की स्वीकृति"}, {"id": "D", "en": "Visitor''s vehicle colour", "hi": "गाड़ी का रंग"}]'::jsonb, 'C', 7),
  ('Security Guard', 'What is an entry register used for?', 'एंट्री रजिस्टर का उपयोग किसलिए किया जाता है?', '[{"id": "A", "en": "Recording visitor details", "hi": "आने वाले लोगों का विवरण दर्ज करने के लिए"}, {"id": "B", "en": "Writing shopping lists", "hi": "खरीदारी की सूची बनाने के लिए"}, {"id": "C", "en": "Recording cooking recipes", "hi": "खाने की रेसिपी लिखने के लिए"}, {"id": "D", "en": "Recording personal expenses", "hi": "निजी खर्च लिखने के लिए"}]'::jsonb, 'A', 8),
  ('Security Guard', 'What should you do if a visitor refuses to follow entry procedures?', 'अगर कोई व्यक्ति प्रवेश के नियमों का पालन करने से मना करे तो क्या करना चाहिए?', '[{"id": "A", "en": "Allow entry anyway", "hi": "फिर भी प्रवेश दें"}, {"id": "B", "en": "Argue aggressively", "hi": "गुस्से में बहस करें"}, {"id": "C", "en": "Politely refuse entry and inform the supervisor", "hi": "विनम्रता से प्रवेश रोकें और सुपरवाइजर को बताएं"}, {"id": "D", "en": "Leave the gate unattended", "hi": "गेट खाली छोड़ दें"}]'::jsonb, 'C', 9),
  ('Security Guard', 'What should you do if you find an unattended bag?', 'अगर आपको कोई लावारिस बैग दिखाई दे तो क्या करना चाहिए?', '[{"id": "A", "en": "Open it immediately", "hi": "तुरंत खोलें"}, {"id": "B", "en": "Take it home", "hi": "घर ले जाएं"}, {"id": "C", "en": "Avoid touching it, keep people away and inform the supervisor", "hi": "उसे न छुएं, लोगों को दूर रखें और सुपरवाइजर को बताएं"}, {"id": "D", "en": "Throw it away", "hi": "फेंक दें"}]'::jsonb, 'C', 10),
  ('Security Guard', 'What should you do if you see a fire?', 'अगर आपको आग दिखाई दे तो क्या करना चाहिए?', '[{"id": "A", "en": "Ignore it", "hi": "नजरअंदाज करें"}, {"id": "B", "en": "Raise the alarm and inform emergency services or the responsible person", "hi": "अलार्म बजाएं और आपातकालीन सेवा या जिम्मेदार व्यक्ति को सूचित करें"}, {"id": "C", "en": "Hide inside a room", "hi": "कमरे में छिप जाएं"}, {"id": "D", "en": "Continue working", "hi": "काम करते रहें"}]'::jsonb, 'B', 11),
  ('Security Guard', 'What is a fire extinguisher used for?', 'फायर एक्सटिंग्विशर का उपयोग किसलिए किया जाता है?', '[{"id": "A", "en": "Cleaning floors", "hi": "फर्श साफ करने के लिए"}, {"id": "B", "en": "Putting out suitable small fires", "hi": "उपयुक्त छोटी आग बुझाने के लिए"}, {"id": "C", "en": "Washing clothes", "hi": "कपड़े धोने के लिए"}, {"id": "D", "en": "Drinking water", "hi": "पानी पीने के लिए"}]'::jsonb, 'B', 12),
  ('Security Guard', 'What should you do when a fire alarm sounds?', 'फायर अलार्म बजने पर आपको क्या करना चाहिए?', '[{"id": "A", "en": "Ignore the alarm", "hi": "अलार्म को नजरअंदाज करें"}, {"id": "B", "en": "Use the lift", "hi": "लिफ्ट का इस्तेमाल करें"}, {"id": "C", "en": "Follow the evacuation procedure and guide people to safety", "hi": "निकासी प्रक्रिया का पालन करें और लोगों को सुरक्षित स्थान पर ले जाएं"}, {"id": "D", "en": "Close your eyes", "hi": "आंखें बंद करें"}]'::jsonb, 'C', 13),
  ('Security Guard', 'What should you do if someone gets injured at the workplace?', 'अगर कार्यस्थल पर किसी व्यक्ति को चोट लग जाए तो क्या करना चाहिए?', '[{"id": "A", "en": "Ignore the injury", "hi": "चोट को नजरअंदाज करें"}, {"id": "B", "en": "Inform the supervisor and arrange appropriate medical help", "hi": "सुपरवाइजर को बताएं और उचित चिकित्सा सहायता की व्यवस्था करें"}, {"id": "C", "en": "Ask the person to leave", "hi": "व्यक्ति को जाने के लिए कहें"}, {"id": "D", "en": "Take photographs only", "hi": "केवल फोटो लें"}]'::jsonb, 'B', 14),
  ('Security Guard', 'What is the emergency exit used for?', 'इमरजेंसी एग्जिट का उपयोग किसलिए होता है?', '[{"id": "A", "en": "Storing equipment", "hi": "सामान रखने के लिए"}, {"id": "B", "en": "Emergency evacuation", "hi": "आपातकाल में बाहर निकलने के लिए"}, {"id": "C", "en": "Taking breaks", "hi": "आराम करने के लिए"}, {"id": "D", "en": "Parking vehicles", "hi": "गाड़ी पार्क करने के लिए"}]'::jsonb, 'B', 15),
  ('Security Guard', 'What should you do if you arrive late for duty?', 'अगर आप ड्यूटी पर देर से पहुंचते हैं तो क्या करना चाहिए?', '[{"id": "A", "en": "Hide from the supervisor", "hi": "सुपरवाइजर से छिपें"}, {"id": "B", "en": "Inform the supervisor honestly", "hi": "सुपरवाइजर को सही जानकारी दें"}, {"id": "C", "en": "Leave the job immediately", "hi": "नौकरी छोड़ दें"}, {"id": "D", "en": "Blame another guard", "hi": "दूसरे गार्ड पर आरोप लगाएं"}]'::jsonb, 'B', 16),
  ('Security Guard', 'Why is a duty handover important?', 'ड्यूटी हैंडओवर करना क्यों जरूरी है?', '[{"id": "A", "en": "To share important information with the next guard", "hi": "अगले गार्ड को जरूरी जानकारी देने के लिए"}, {"id": "B", "en": "To avoid working", "hi": "काम से बचने के लिए"}, {"id": "C", "en": "To waste time", "hi": "समय बर्बाद करने के लिए"}, {"id": "D", "en": "To leave without informing anyone", "hi": "बिना बताए जाने के लिए"}]'::jsonb, 'A', 17),
  ('Security Guard', 'What should you do if someone offers you money to allow unauthorised entry?', 'अगर कोई व्यक्ति बिना अनुमति प्रवेश देने के लिए आपको पैसे दे तो क्या करना चाहिए?', '[{"id": "A", "en": "Accept the money", "hi": "पैसे ले लें"}, {"id": "B", "en": "Allow entry", "hi": "प्रवेश दे दें"}, {"id": "C", "en": "Refuse and report the incident", "hi": "मना करें और घटना की रिपोर्ट करें"}, {"id": "D", "en": "Ignore the rules", "hi": "नियमों को नजरअंदाज करें"}]'::jsonb, 'C', 18),
  ('Security Guard', 'What should you do if you notice a security camera is not working?', 'अगर आपको पता चले कि सिक्योरिटी कैमरा काम नहीं कर रहा है तो क्या करना चाहिए?', '[{"id": "A", "en": "Ignore it", "hi": "नजरअंदाज करें"}, {"id": "B", "en": "Report it to the supervisor", "hi": "सुपरवाइजर को बताएं"}, {"id": "C", "en": "Break another camera", "hi": "दूसरा कैमरा तोड़ दें"}, {"id": "D", "en": "Switch off all cameras", "hi": "सभी कैमरे बंद कर दें"}]'::jsonb, 'B', 19),
  ('Security Guard', 'How should a security guard behave with visitors and employees?', 'सिक्योरिटी गार्ड को आगंतुकों और कर्मचारियों के साथ कैसा व्यवहार करना चाहिए?', '[{"id": "A", "en": "Rudely", "hi": "रूखे तरीके से"}, {"id": "B", "en": "Aggressively", "hi": "आक्रामक तरीके से"}, {"id": "C", "en": "Politely and professionally", "hi": "विनम्रता और पेशेवर तरीके से"}, {"id": "D", "en": "Ignore everyone", "hi": "सभी को नजरअंदाज करके"}]'::jsonb, 'C', 20);
